from rich.cells import get_character_cell_size

def mock_cell_len(text, unicode_version="auto"):
    total_width = 0
    last_measured_character = None
    SPECIAL = {"\u200d", "\ufe0f"}
    iter_characters = iter(text)
    for character in iter_characters:
        if character in SPECIAL:
            if character == "\u200d":
                try:
                    next_char = next(iter_characters)
                    if (
                        last_measured_character
                        and get_character_cell_size(last_measured_character, unicode_version) == 2
                        and get_character_cell_size(next_char, unicode_version) == 2
                    ):
                        pass
                    else:
                        total_width += get_character_cell_size(next_char, unicode_version)
                        last_measured_character = next_char
                except StopIteration:
                    pass
            elif last_measured_character:
                # Simplified for this test
                pass
        else:
            if character_width := get_character_cell_size(character, unicode_version):
                last_measured_character = character
                total_width += character_width
    return total_width

test_cases = [
    ("A", 1),
    ("A\u200dB", 2),
    ("\U0001F468\u200d\U0001F469", 2), # 👨‍👩
    ("A\u200d\U0001F468", 3), # A + ZWJ + 👨
    ("\U0001F468\u200dA", 3), # 👨 + ZWJ + A
    ("\U0001F468\u200d\U0001F469\u200d\U0001F467", 2), # 👨‍👩‍👧
    ("A\u200d\u200dB", 2),
    ("\U0001F468\u200d\u200d\U0001F469", 4), # 👨 + ZWJ + ZWJ + 👩
]

for text, expected in test_cases:
    actual = mock_cell_len(text)
    print(f"Text: {text!r}, Expected: {expected}, Actual: {actual}, {'OK' if actual == expected else 'FAIL'}")
